buggy.described_examples:
import numpy as np
import pandas as pd
from pandas import DatetimeIndex, Timedelta

try:
    from pandas._libs.tslibs import iNaT
except Exception:
    try:
        from pandas._libs.tslib import iNaT
    except Exception:
        iNaT = pd.NaT.value

_name = "dti = DatetimeIndex(np.array([iNaT + 1], dtype='M8[ns]'), tz='UTC'); obj + Timedelta(-1, unit) for unit in ['s','ms','us','ns']"

try:
    dti = DatetimeIndex(np.array([iNaT + 1], dtype='M8[ns]'), tz='UTC')
    obj = dti
    results = [(unit, obj + Timedelta(-1, unit)) for unit in ['s', 'ms', 'us', 'ns']]
    probe(_name, [(unit, str(res)) for unit, res in results])
except Exception as e:
    probe_exception(_name, e)

